```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,1) p50_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('SELECT Trip','SELECT ts.trip2') GROUP BY 1,2,3", "claim": "travel2 'SELECT Trip' p95 jumped to ~30 s while p50 stayed ~1 ms; the DB client span stays ~1 ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name='SELECT Trip' GROUP BY 1,2,3", "claim": "Normal period: travel2 'SELECT Trip' p95 is about 14 ms over 388 spans."},
        {"kind": "log", "sql": "SELECT level, message, COUNT(*) n FROM abnormal_logs WHERE service_name='ts-travel2-service' AND message ILIKE '%Hikari%' GROUP BY 1,2", "claim": "travel2 logs HikariPool 'Connection is not available, request timed out after 30000ms' errors."},
        {"kind": "metric", "sql": "SELECT metric, ROUND(AVG(value),2) avgv, ROUND(MAX(value),2) maxv FROM abnormal_metrics WHERE service_name='ts-travel2-service' AND metric IN ('db.client.connections.pending_requests','db.client.connections.timeouts','db.client.connections.max') GROUP BY 1", "claim": "travel2 DB pool max is 10 with pending requests up to 6 and connection timeouts during the incident."},
        {"kind": "metric", "sql": "SELECT metric, ROUND(AVG(value),1) avgv, ROUND(MAX(value),1) maxv FROM abnormal_metrics WHERE service_name='ts-travel2-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1", "claim": "travel2 container CPU and memory stay at or below normal levels; no resource saturation."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms, SUM(CASE WHEN attr_http_response_status_code>=500 THEN 1 ELSE 0 END) http5xx FROM abnormal_traces WHERE attr_span_kind='Client' AND service_name='ts-route-plan-service' AND span_name='POST' GROUP BY 1,2", "claim": "route-plan's outgoing POST calls to travel2 reach 60 s p95 with 8 HTTP 5xx responses; normal p95 was 1.3 s."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms, SUM(CASE WHEN attr_http_response_status_code>=500 THEN 1 ELSE 0 END) http5xx FROM abnormal_traces WHERE attr_span_kind='Client' AND service_name='ts-travel-plan-service' AND span_name='POST' GROUP BY 1,2", "claim": "travel-plan's outgoing POST calls to route-plan reach 60 s p95 with 9 HTTP 5xx responses."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name='ts-ui-dashboard' AND span_name LIKE '%travelPlan%' GROUP BY 1,2", "claim": "ui-dashboard travelPlan requests reach ~20-60 s p95 in the incident, up from normal levels."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name='ts-ui-dashboard' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY 1,2", "claim": "ui-dashboard's trips/left requests to travel2 reach about 20 s p95 during the incident."}]}
  ]
}
